import React, { useEffect, useState } from 'react'
import {Link} from "react-router-dom";
import './Reports.css'
import axios from "axios";




export default function Reports() {

    const [user, setUser] = useState(null);
    const localUser = JSON.parse(localStorage.getItem('user'));
    const [userRole, setUserRole] = useState(null);
    // Состояние для данных о доступе к инструментам
    const [accessData, setAccessData] = useState([]);





        // Мокап данных о доступе (загрузка с сервера или статический)
        useEffect(() => {
            // Загрузка данных о доступе с сервера или установка статических данных
            const mockAccessData = [
                { roleId: 1, toolId: 1, isAccessible: true },
                // ... остальные данные
            ];
            setAccessData(mockAccessData);

            // Установка роли пользователя (для демонстрации)
            setUserRole(1); // Ваша роль пользователя


        const getUser = async () => {

                const response = await axios.get('/api/user/' + localUser._id);
                setUser(response.data);
        };
        getUser();

    }, [localUser._id]);

    const isAccessible = (toolId) => {
        const access = accessData.find(item => item.role_id === userRole && item.tool_id === tool_id);
        return access ? access.is_accessible : false;
    };


    return (
        <>
            <div className="ReportsButton">
                {user === null ? (
                    <div></div>
                ) : (
                    <>
                        {(user.role_id === '3' || user.role_id === '4') && (
                            <Link to='/ReportsHistory' className='linkReports'>Отчет по истории</Link>
                        )}
                        <br/>
                        {(user.role_id=== '2' || user.role_id === '3' || user.role_id === '4') && (
                            <Link to='/ReportsNominations' className='linkReports'>Отчет по номинациям</Link>
                        )}
                    </>
                )}
            </div>
        </>
    );
}
